#!/usr/bin/env python3
"""Write Platinum's window buttons (PlatinumButtons.h) from its artwork in
src/third_party/platinum/art. Needs rsvg-convert and Pillow. The artwork draws
them at three times their size, in steps of three pixels.

    python3 -I tools/make-platinum-art.py
"""

import io
import os
import subprocess

from PIL import Image

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
PLATINUM = os.path.join(ROOT, "src", "third_party", "platinum")
ART = os.path.join(PLATINUM, "art")

HEADER = """/*
 * Generated by tools/make-platinum-art.py from Niels's Platinum window decoration.
 * Distributed under the terms of the GNU GPL, version 3 or later.
 */
"""


def button(svg, state):
	data = subprocess.run(["rsvg-convert", "-i", state + "-center",
		os.path.join(ART, svg)], check=True, capture_output=True).stdout
	image = Image.open(io.BytesIO(data)).convert("RGBA")
	return image.crop((0, 0, 42, 42)).resize((14, 14), Image.NEAREST)


def table(name, image):
	width, height = image.size
	data = image.tobytes()
	pixels = [(data[i + 3] << 24) | (data[i] << 16) | (data[i + 1] << 8) | data[i + 2]
		for i in range(0, len(data), 4)]
	lines = ["static const uint32 %s[%d] = {" % (name, width * height)]
	for start in range(0, len(pixels), width):
		lines.append("\t" + ", ".join("0x%08x" % p
			for p in pixels[start:start + width]) + ",")
	lines.append("};")
	return "\n".join(lines) + "\n"


out = [HEADER, "#ifndef PLATINUM_BUTTONS_H\n#define PLATINUM_BUTTONS_H\n\n",
	"// ARGB, row by row: the large ones for most windows, the small ones for "
	"floating\n// windows\n",
	"static const int32 kLargeButton = 14;\n",
	"static const int32 kSmallButton = 10;\n\n"]
for svg, name in (("close.svg", "Close"), ("maximize.svg", "Zoom"),
		("minimize.svg", "Minimize")):
	for state, stateName in (("active", "Active"), ("pressed", "Pressed")):
		image = button(svg, state)
		out.append(table("k%s%sLarge" % (name, stateName), image))
		small = image.resize((10, 10), Image.LANCZOS)
		out.append(table("k%s%sSmall" % (name, stateName), small))
out.append("\n#endif	// PLATINUM_BUTTONS_H\n")
with open(os.path.join(PLATINUM, "decorator", "PlatinumButtons.h"), "w") as f:
	f.write("".join(out))
